{"implementation": "def solve(case):
    segments = case['segments']
    budget = case['budget']
    n = len(segments)
    alloc = [seg['minimum'] for seg in segments]
    remaining = budget - sum(alloc)
    sorted_indices = sorted(range(n), key=lambda i: (-segments[i]['importance'], i))
    while remaining > 0:
        gave = False
        for i in sorted_indices:
            if alloc[i] < segments[i]['capacity']:
                alloc[i] += 1
                remaining -= 1
                gave = True
                break
        if not gave:
            break
    by_name = {segments[i]['name']: alloc[i] for i in range(n)}
    total = sum(alloc)
    return {'allocations': alloc, 'by_name': by_name, 'total': total}
"}
